/*
 * Live counter for the CNDWN countdown pages, overview and embed widget
 * (generated by tools/countdown-pages.mjs; this file is hand-written).
 *
 * Every [data-cd] element carries the upcoming dates of one occasion:
 *   data-dates="2026-12-25,2027-12-25"      all-day: counts to local midnight
 *   data-instants="2027-03-20T20:24:00Z"     exact moment (equinoxes, solstices)
 * and may contain any of [data-cd-days] [data-cd-unit] [data-cd-clock]
 * [data-cd-until] [data-cd-weeks] [data-cd-sleeps] [data-cd-hours].
 * Strings come from <script id="cd-i18n" type="application/json">.
 * During an all-day occasion the element gets the class "today".
 */
(function () {
  var S;
  try { S = JSON.parse(document.getElementById('cd-i18n').textContent); } catch (e) { return; }
  var DAY = 864e5;

  function f(tpl, v) { return tpl.replace(/\{(\w+)\}/g, function (m, k) { return k in v ? v[k] : m; }); }
  function num(n) { return n.toLocaleString(S.locale); }
  function midnight(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
  function calDays(from, to) {
    return Math.round((Date.UTC(to.getFullYear(), to.getMonth(), to.getDate()) - Date.UTC(from.getFullYear(), from.getMonth(), from.getDate())) / DAY);
  }

  function targets(el) {
    if (el.dataset.dates) {
      return el.dataset.dates.split(',').map(function (s) {
        var p = s.split('-');
        return { start: new Date(+p[0], +p[1] - 1, +p[2]), allDay: true };
      });
    }
    return (el.dataset.instants || '').split(',').filter(Boolean).map(function (s) { return { start: new Date(s), allDay: false }; });
  }

  function next(list, now) {
    for (var i = 0; i < list.length; i++) {
      var t = list[i];
      var end = t.allDay ? new Date(t.start.getFullYear(), t.start.getMonth(), t.start.getDate() + 1) : t.start;
      if (now < end) return t;
    }
    return null;
  }

  function fmtDate(t) {
    var o = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
    if (!t.allDay) { o.hour = 'numeric'; o.minute = '2-digit'; }
    return new Intl.DateTimeFormat(S.locale, o).format(t.start);
  }

  function set(el, sel, text) {
    var n = el.querySelectorAll(sel);
    for (var i = 0; i < n.length; i++) n[i].textContent = text;
  }

  var els = Array.prototype.slice.call(document.querySelectorAll('[data-cd]'));
  var lists = els.map(targets);

  function tick() {
    var now = new Date();
    els.forEach(function (el, i) {
      var t = next(lists[i], now);
      if (!t) return;
      var today = t.allDay && now >= t.start;
      el.classList.toggle('today', today);
      var ms = Math.max(0, t.start - now);
      var days = t.allDay ? calDays(now, t.start) : Math.floor(ms / DAY);
      set(el, '[data-cd-days]', num(days));
      set(el, '[data-cd-unit]', days === 1 ? S.day : S.days);
      var h = Math.floor(ms / 36e5), m = Math.floor(ms / 6e4) % 60, s = Math.floor(ms / 1e3) % 60;
      set(el, '[data-cd-clock]', Math.floor(h / 24) + 'd ' + (h % 24) + 'h ' + ('0' + m).slice(-2) + 'm ' + ('0' + s).slice(-2) + 's');
      set(el, '[data-cd-until]', f(S.until, { date: fmtDate(t) }));
      set(el, '[data-cd-weeks]', f(S.weeksVal || '', { w: num(Math.floor(days / 7)), d: days % 7 }));
      set(el, '[data-cd-sleeps]', f(S.sleepsVal || '', { n: num(calDays(now, t.start)) }));
      set(el, '[data-cd-hours]', f(S.hoursVal || '', { n: num(h) }));
    });
  }

  tick();
  setInterval(tick, 1000);

  // "Copy code" buttons for the embed snippet
  document.addEventListener('click', function (e) {
    var b = e.target.closest && e.target.closest('[data-copy]');
    if (!b) return;
    var src = document.getElementById(b.getAttribute('data-copy'));
    if (!src) return;
    var done = function () { var t = b.textContent; b.textContent = b.getAttribute('data-copied'); setTimeout(function () { b.textContent = t; }, 1600); };
    if (navigator.clipboard) navigator.clipboard.writeText(src.value).then(done, function () { src.select(); });
    else { src.select(); document.execCommand('copy'); done(); }
  });
})();
